   /* Internal startIdx-anchored open behind cdlKickingOpen (composition seam). */
   CdlKickingStream cdlKickingOpenInternal( double inOpen[], double inHigh[], double inLow[], double inClose[], int startIdx )
   {
      CdlKickingStream sp = new CdlKickingStream(this);
      RetCode retCode = cdlKickingOpenBody(sp, inOpen, inHigh, inLow, inClose, startIdx);
      if( retCode == RetCode.Success ) {
         return sp;
      }
      if( retCode == RetCode.OutOfRangeEndIndex ) {
         throw new InsufficientHistoryException("TA_CDLKICKING open: history shorter than lookback + 1");
      }
      if( retCode == RetCode.InternalError ) {
         throw new IllegalStateException("TA_CDLKICKING open: internal error");
      }
      throw new IllegalArgumentException("TA_CDLKICKING open: " + retCode);
   }
   /**
    * Open a live CDLKICKING stream over the warm-up history; the handle's
    * {@code value()} starts at the last history bar's value — bit-identical
    * to {@link Core#cdlKicking} at that bar.
    * <p>The history must hold at least {@code cdlKickingLookback(...) + 1} bars
    * (unstable-period aware), or {@link InsufficientHistoryException} is
    * thrown. Out-of-range parameters throw {@link IllegalArgumentException}
    * ({@code Integer.MIN_VALUE} selects an integer parameter's documented
    * default, as in the batch API).
    */
   public CdlKickingStream cdlKickingOpen( double inOpen[], double inHigh[], double inLow[], double inClose[] )
   {
      return cdlKickingOpenInternal(inOpen, inHigh, inLow, inClose, 0);
   }
   /**
    * {@link Core#cdlKickingOpen} that also fills the output array(s) bit-identically
    * to {@link Core#cdlKicking} over the whole history in the same single pass
    * (no separate batch call needed for the warm-up plot). Output arrays must
    * not alias the inputs or each other, and must hold
    * {@code historyLen - lookback} values.
    */
   public CdlKickingStream cdlKickingOpenAndFill( double inOpen[], double inHigh[], double inLow[], double inClose[], MInteger outBegIdx, MInteger outNBElement, int outInteger[] )
   {
      CdlKickingStream sp = new CdlKickingStream(this);
      RetCode retCode = cdlKickingOpenAndFillBody(sp, inOpen, inHigh, inLow, inClose, outBegIdx, outNBElement, outInteger);
      if( retCode == RetCode.Success ) {
         return sp;
      }
      if( retCode == RetCode.OutOfRangeEndIndex ) {
         throw new InsufficientHistoryException("TA_CDLKICKING openAndFill: history shorter than lookback + 1");
      }
      if( retCode == RetCode.InternalError ) {
         throw new IllegalStateException("TA_CDLKICKING openAndFill: internal error");
      }
      throw new IllegalArgumentException("TA_CDLKICKING openAndFill: " + retCode);
   }
