   /* Internal startIdx-anchored open behind cdlKickingByLengthOpen (composition seam). */
   CdlKickingByLengthStream cdlKickingByLengthOpenInternal( double inOpen[], double inHigh[], double inLow[], double inClose[], int startIdx )
   {
      CdlKickingByLengthStream sp = new CdlKickingByLengthStream(this);
      RetCode retCode = cdlKickingByLengthOpenBody(sp, inOpen, inHigh, inLow, inClose, startIdx);
      if( retCode == RetCode.Success ) {
         return sp;
      }
      if( retCode == RetCode.OutOfRangeEndIndex ) {
         throw new InsufficientHistoryException("TA_CDLKICKINGBYLENGTH open: history shorter than lookback + 1");
      }
      if( retCode == RetCode.InternalError ) {
         throw new IllegalStateException("TA_CDLKICKINGBYLENGTH open: internal error");
      }
      throw new IllegalArgumentException("TA_CDLKICKINGBYLENGTH open: " + retCode);
   }
   /**
    * Open a live CDLKICKINGBYLENGTH stream over the warm-up history; the handle's
    * {@code value()} starts at the last history bar's value — bit-identical
    * to {@link Core#cdlKickingByLength} at that bar.
    * <p>The history must hold at least {@code cdlKickingByLengthLookback(...) + 1} bars
    * (unstable-period aware), or {@link InsufficientHistoryException} is
    * thrown. Out-of-range parameters throw {@link IllegalArgumentException}
    * ({@code Integer.MIN_VALUE} selects an integer parameter's documented
    * default, as in the batch API).
    */
   public CdlKickingByLengthStream cdlKickingByLengthOpen( double inOpen[], double inHigh[], double inLow[], double inClose[] )
   {
      return cdlKickingByLengthOpenInternal(inOpen, inHigh, inLow, inClose, 0);
   }
   /**
    * {@link Core#cdlKickingByLengthOpen} that also fills the output array(s) bit-identically
    * to {@link Core#cdlKickingByLength} over the whole history in the same single pass
    * (no separate batch call needed for the warm-up plot). Output arrays must
    * not alias the inputs or each other, and must hold
    * {@code historyLen - lookback} values.
    */
   public CdlKickingByLengthStream cdlKickingByLengthOpenAndFill( double inOpen[], double inHigh[], double inLow[], double inClose[], MInteger outBegIdx, MInteger outNBElement, int outInteger[] )
   {
      CdlKickingByLengthStream sp = new CdlKickingByLengthStream(this);
      RetCode retCode = cdlKickingByLengthOpenAndFillBody(sp, inOpen, inHigh, inLow, inClose, outBegIdx, outNBElement, outInteger);
      if( retCode == RetCode.Success ) {
         return sp;
      }
      if( retCode == RetCode.OutOfRangeEndIndex ) {
         throw new InsufficientHistoryException("TA_CDLKICKINGBYLENGTH openAndFill: history shorter than lookback + 1");
      }
      if( retCode == RetCode.InternalError ) {
         throw new IllegalStateException("TA_CDLKICKINGBYLENGTH openAndFill: internal error");
      }
      throw new IllegalArgumentException("TA_CDLKICKINGBYLENGTH openAndFill: " + retCode);
   }
