   /* Internal startIdx-anchored open behind cdlOnNeckOpen (composition seam). */
   CdlOnNeckStream cdlOnNeckOpenInternal( double inOpen[], double inHigh[], double inLow[], double inClose[], int startIdx )
   {
      CdlOnNeckStream sp = new CdlOnNeckStream(this);
      RetCode retCode = cdlOnNeckOpenBody(sp, inOpen, inHigh, inLow, inClose, startIdx);
      if( retCode == RetCode.Success ) {
         return sp;
      }
      if( retCode == RetCode.OutOfRangeEndIndex ) {
         throw new InsufficientHistoryException("TA_CDLONNECK open: history shorter than lookback + 1");
      }
      if( retCode == RetCode.InternalError ) {
         throw new IllegalStateException("TA_CDLONNECK open: internal error");
      }
      throw new IllegalArgumentException("TA_CDLONNECK open: " + retCode);
   }
   /**
    * Open a live CDLONNECK stream over the warm-up history; the handle's
    * {@code value()} starts at the last history bar's value — bit-identical
    * to {@link Core#cdlOnNeck} at that bar.
    * <p>The history must hold at least {@code cdlOnNeckLookback(...) + 1} bars
    * (unstable-period aware), or {@link InsufficientHistoryException} is
    * thrown. Out-of-range parameters throw {@link IllegalArgumentException}
    * ({@code Integer.MIN_VALUE} selects an integer parameter's documented
    * default, as in the batch API).
    */
   public CdlOnNeckStream cdlOnNeckOpen( double inOpen[], double inHigh[], double inLow[], double inClose[] )
   {
      return cdlOnNeckOpenInternal(inOpen, inHigh, inLow, inClose, 0);
   }
   /**
    * {@link Core#cdlOnNeckOpen} that also fills the output array(s) bit-identically
    * to {@link Core#cdlOnNeck} over the whole history in the same single pass
    * (no separate batch call needed for the warm-up plot). Output arrays must
    * not alias the inputs or each other, and must hold
    * {@code historyLen - lookback} values.
    */
   public CdlOnNeckStream cdlOnNeckOpenAndFill( double inOpen[], double inHigh[], double inLow[], double inClose[], MInteger outBegIdx, MInteger outNBElement, int outInteger[] )
   {
      CdlOnNeckStream sp = new CdlOnNeckStream(this);
      RetCode retCode = cdlOnNeckOpenAndFillBody(sp, inOpen, inHigh, inLow, inClose, outBegIdx, outNBElement, outInteger);
      if( retCode == RetCode.Success ) {
         return sp;
      }
      if( retCode == RetCode.OutOfRangeEndIndex ) {
         throw new InsufficientHistoryException("TA_CDLONNECK openAndFill: history shorter than lookback + 1");
      }
      if( retCode == RetCode.InternalError ) {
         throw new IllegalStateException("TA_CDLONNECK openAndFill: internal error");
      }
      throw new IllegalArgumentException("TA_CDLONNECK openAndFill: " + retCode);
   }
