      sp.prevHigh = prevHigh;
      sp.prevLow = prevLow;
      sp.prevClose = prevClose;
      sp.prevMinusDM = prevMinusDM;
      sp.prevPlusDM = prevPlusDM;
      sp.prevTR = prevTR;
      sp.tempReal = tempReal;
      sp.diffP = diffP;
      sp.diffM = diffM;
      sp.minusDI = minusDI;
      sp.plusDI = plusDI;
      sp.lastOut_outReal = lastValue_outReal;
      sp.cur_outReal = lastValue_outReal;
